import assert from 'node:assert/strict'
import test from 'node:test'
// eslint-disable-next-line n/no-unpublished-import -- Tests use build output generated by yarn test.
import { compareValue, parseVariableMappings, VistaState } from '../dist/core/state.js'

test('mapping parser supports comments, CRLF, shared addresses and argument selection', () => {
	assert.deepEqual(parseVariableMappings('# Example\r\ncue = /show/cue\r\nname=/show/cue 2\nempty=/'), {
		mappings: [
			{ id: 'cue', address: '/show/cue', argument: 1 },
			{ id: 'name', address: '/show/cue', argument: 2 },
			{ id: 'empty', address: '/', argument: 1 },
		],
		errors: [],
	})
	assert.deepEqual(parseVariableMappings(), { mappings: [], errors: [] })
})

test('invalid mappings are reported without discarding valid lines', () => {
	const { mappings, errors } = parseVariableMappings(
		'good=/test\ngood=/other\nosc_listening=/test\n__proto__=/test\nconstructor=/test\nbad-id=/test\nno_slash=test\nwild=/test/*\nzero=/test 0\nhuge=/test 65\nmissing=\nlast=/valid 64',
	)
	assert.deepEqual(
		mappings.map(({ id }) => id),
		['good', 'last'],
	)
	assert.equal(errors.length, 10)
	assert.match(errors[0], /Line 2/)
})

test('state updates only matching mappings and preserves zero, false and empty strings', () => {
	const state = new VistaState()
	state.mappings = parseVariableMappings('cue=/cue\nlabel=/cue 2\nflag=/flag').mappings
	state.receive('/cue', [0, ''])
	state.receive('/flag', [false])
	state.receive('/unmapped', [99])
	assert.deepEqual(Object.fromEntries(state.values), { cue: 0, label: '', flag: false })
	assert.equal(state.messagesReceived, 3)
	assert.equal(state.lastAddress, '/unmapped')
	assert.equal(state.lastValue, 99)
	state.receive('/cue', [1])
	assert.equal(state.values.get('cue'), 1)
	assert.equal(state.values.has('label'), false)
	for (const unsupported of [NaN, Infinity, {}, [], Buffer.from('blob'), null, undefined]) {
		state.receive('/flag', [unsupported])
		assert.equal(state.values.has('flag'), false)
		assert.equal(state.lastValue, undefined)
	}
	state.listening = true
	state.reset()
	assert.equal(state.listening, false)
	assert.equal(state.messagesReceived, 0)
	assert.equal(state.values.size, 0)
	assert.equal(state.lastAddress, '')
	assert.equal(state.lastValue, undefined)
	assert.equal(state.mappings.length, 3)
})

test('feedback comparisons handle text, numeric strings, OSC floats and boolean encodings', () => {
	for (const mode of ['eq', 'ne', 'num_eq', 'gt', 'gte', 'lt', 'lte', 'on', 'off', 'known']) {
		assert.equal(compareValue(undefined, mode, '1'), false, mode)
	}
	assert.equal(compareValue('001', 'eq', '1'), false)
	assert.equal(compareValue('001', 'num_eq', '1'), true)
	assert.equal(compareValue('Intro', 'eq', 'Intro'), true)
	assert.equal(compareValue('Intro', 'ne', 'intro'), true)
	assert.equal(compareValue(0.3000000119, 'num_eq', '0.3'), true)
	assert.equal(compareValue(0.4, 'num_eq', '0.3'), false)
	assert.equal(compareValue('0.6', 'gt', '0.5'), true)
	assert.equal(compareValue(0.5, 'gte', '0.5'), true)
	assert.equal(compareValue(0.4, 'lt', '0.5'), true)
	assert.equal(compareValue(0.5, 'lte', '0.5'), true)
	for (const value of [true, 1, '1', 'true']) assert.equal(compareValue(value, 'on', ''), true)
	for (const value of [false, 0, '0', 'false']) assert.equal(compareValue(value, 'off', ''), true)
	for (const value of ['', 'text', 'NaN', 'Infinity', false]) {
		assert.equal(compareValue(value, 'num_eq', '0'), false)
	}
	assert.equal(compareValue(0, 'num_eq', ''), false)
	assert.equal(compareValue('', 'known', ''), true)
	assert.equal(compareValue(0, 'known', ''), true)
	assert.equal(compareValue(false, 'known', ''), true)
})
